function student_import_norm(string $value):string {
 $value=trim($value);
 if(function_exists('mb_strtolower'))return mb_strtolower($value,'UTF-8');
 return strtolower(strtr($value,['Á'=>'á','É'=>'é','Í'=>'í','Ó'=>'ó','Ú'=>'ú','Ü'=>'ü','Ñ'=>'ñ','À'=>'à','È'=>'è','Ì'=>'ì','Ò'=>'ò','Ù'=>'ù','Ç'=>'ç']));
}
function student_age(string $dob):?int{if($dob==='')return null;$dt=DateTimeImmutable::createFromFormat('!Y-m-d',$dob);$today=new DateTimeImmutable('today');return $dt&&$dt->format('Y-m-d')===$dob&&$dt<=$today?$dt->diff($today)->y:null;}
