function urlv(string $v,string $c='',string $e=''): string {return 'index.php?'.http_build_query(array_filter(['v'=>$v,'c'=>$c,'e'=>$e],fn($x)=>$x!==''));}
function a(string $v,string $label,string $c='',string $e='',string $class=''): void {echo '<a class="'.h($class).'" href="'.h(urlv($v,$c,$e)).'">'.h($label).'</a>';}
